// Verus solution for constructing a length-n sequence over {'a','b'} such that
// for all i in 0..=n-3, s[i] != s[i+2].
//
// Key idea: alternate "a","b","a","b",...
// Then positions i and i+2 always differ.

#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn solve(n: i8) -> (result: Vec<char>)
    requires
        n >= 1,
        // We'll use n as a usize for indexing/length, so require it fits.
        n as int <= usize::MAX as int,
    ensures
        result.len() == n as usize,
        // Only 'a' or 'b' (no 'c' used)
        forall|i: int| 0 <= i < result.len() ==> (result[i] == 'a' || result[i] == 'b'),
        // Constraint: for all i with 0 <= i <= n-3, result[i] != result[i+2]
        forall|i: int|
            0 <= i && i + 2 < result.len()
            ==> result[i] != result[i + 2],
{
    let mut v: Vec<char> = Vec::new();
    let nu: usize = n as usize;

    let mut i: usize = 0;
    while i < nu
        invariant
            v.len() == i,
            i <= nu,
            // Only 'a' or 'b' so far
            forall|k: int| 0 <= k < v.len() ==> (v[k] == 'a' || v[k] == 'b'),
            // v[k] is 'a' iff k even; 'b' iff k odd
            forall|k: int| 0 <= k < v.len() ==> (v[k] == if k % 2 == 0 { 'a' } else { 'b' }),
            // The i -> i+2 constraint holds for all indices already in v
            forall|k: int|
                0 <= k && k + 2 < v.len()
                ==> v[k] != v[k + 2],
        decreases nu - i
    {
        let ch = if i % 2 == 0 { 'a' } else { 'b' };
        v.push(ch);

        // After pushing, re-establish the i->i+2 constraint for the new tail.
        // Only the pair (i-2, i) could be newly formed.
        if i >= 2 {
            // i-2 and i have opposite parity, hence different chars.
            assert(v[(i - 2) as int] == if ((i - 2) as int) % 2 == 0 { 'a' } else { 'b' });
            assert(v[i as int] == if (i as int) % 2 == 0 { 'a' } else { 'b' });
            assert(((i - 2) as int) % 2 != (i as int) % 2);
            assert(v[(i - 2) as int] != v[i as int]);
        }

        i = i + 1;
    }

    v
}

} // verus!